-- 209: Help Center — the Personal data breaches topic, and Data Breaches in the menu and
-- role descriptions. Same pattern as db/204: sets the English ahead of the app's sync,
-- marks other translations of a changed text out of date, adds the Arabic draft
-- (AI_TRANSLATED), never replaces a translation a person has edited or verified.
-- Safe to run more than once.

BEGIN;

CREATE TEMP TABLE _tr209 (key_code text, base_text text, ar_text text) ON COMMIT DROP;

INSERT INTO _tr209 (key_code, base_text, ar_text) VALUES
  ('helpdoc.data-breaches.title', E'Personal data breaches', E'خروقات البيانات الشخصية'),
  ('helpdoc.data-breaches.summary', E'Record every breach of personal data, see which data and people it affects, and notify the regulator within 72 hours.', E'سجّل كل خرق للبيانات الشخصية، واعرف البيانات والأشخاص الذين يمسّهم، وأشعر الجهة المختصة خلال 72 ساعة.'),
  ('helpdoc.data-breaches.what.title', E'What it is', E'ما هو'),
  ('helpdoc.data-breaches.what.body', E'The breach register under **Data Privacy › Data Breaches** records every suspected or confirmed breach of personal data, whether or not it has to be reported, as the Saudi PDPL and the GDPR require. For each breach it keeps:\n- what happened, when the organisation became aware of it, the kind of breach and its cause;\n- the **affected data**: the systems, tables or columns involved, with the catalog''s facts about the personal data in them (categories, sensitive data, row counts, copies elsewhere, sharing);\n- the **risk** to the people concerned;\n- the **notifications**: to the regulator, and to the people concerned;\n- the **measures** taken to contain it and prevent it happening again, and a timeline of every step.', E'يسجّل سجل الخروقات في **خصوصية البيانات › خروقات البيانات** كل خرق مشتبه به أو مؤكد للبيانات الشخصية، سواء وجب الإبلاغ عنه أم لا، كما يشترط نظام حماية البيانات الشخصية السعودي واللائحة الأوروبية. ويحفظ لكل خرق:\n- ما الذي حدث، ومتى علمت الجهة به، ونوع الخرق وسببه؛\n- **البيانات المتأثرة**: الأنظمة أو الجداول أو الأعمدة المعنية، مع حقائق الكتالوج عن البيانات الشخصية فيها (الفئات، والبيانات الحساسة، وعدد الصفوف، والنسخ في أماكن أخرى، والمشاركة)؛\n- **الخطر** على أصحاب البيانات؛\n- **الإشعارات**: للجهة المختصة، ولأصحاب البيانات؛\n- **الإجراءات** المتخذة لاحتوائه ومنع تكراره، وسجلاً زمنياً لكل خطوة.'),
  ('helpdoc.data-breaches.value.title', E'Business value', E'القيمة للأعمال'),
  ('helpdoc.data-breaches.value.body', E'- Meets the PDPL and GDPR duty to notify the regulator within 72 hours and to document every breach.\n- In minutes, the catalog shows which personal data was in the affected systems and how many people it may concern, instead of a manual investigation.\n- Deadline reminders, and a regulator report ready to send.', E'- يفي بواجب إشعار الجهة المختصة خلال 72 ساعة وتوثيق كل خرق وفق نظام حماية البيانات الشخصية واللائحة الأوروبية.\n- يعرض الكتالوج في دقائق البيانات الشخصية التي كانت في الأنظمة المتأثرة وعدد من قد يمسّهم الخرق، بدلاً من تحقيق يدوي.\n- تذكيرات بالمهلة، وتقرير جاهز لإرساله إلى الجهة المختصة.'),
  ('helpdoc.data-breaches.deadline.title', E'The 72-hour deadline and what must be notified', E'مهلة الـ72 ساعة وما يجب الإشعار به'),
  ('helpdoc.data-breaches.deadline.body', E'The regulator must be notified within **72 hours of the organisation becoming aware** of the breach (PDPL Implementing Regulation, art. 24; GDPR art. 33). The clock starts from the time recorded as *When the organisation became aware*.\n\n| Risk to the people concerned | Regulator | Data subjects |\n|---|---|---|\n| Not assessed yet | Required: the deadline applies until the risk is assessed | — |\n| Unlikely to put people at risk | Not required; record why | Not required |\n| Risk to people | Required within 72 hours | Not required |\n| High risk to people | Required within 72 hours | Required without undue delay, or record why not |\n\nWhen the affected assets hold personal data, the catalog suggests a level: **High** for sensitive categories, large scale (100,000 rows or more) or unencrypted personal data columns, otherwise **Risk**; **Unlikely** when they hold none. The officer decides.\n\nThe register shows for each breach whether the notice is due, due within 24 hours, overdue, or was made on time or late. An hourly check reminds the handler and the compliance officers once when less than 24 hours are left and once when the deadline has passed (Configuration › Scheduling › Data breaches).', E'يجب إشعار الجهة المختصة خلال **72 ساعة من علم الجهة** بالخرق (اللائحة التنفيذية لنظام حماية البيانات الشخصية، المادة 24؛ واللائحة الأوروبية، المادة 33). وتبدأ المهلة من الوقت المسجّل في *متى علمت الجهة بالخرق*.\n\n| الخطر على أصحاب البيانات | الجهة المختصة | أصحاب البيانات |\n|---|---|---|\n| لم يُقيَّم بعد | مطلوب: تسري المهلة إلى أن يُقيَّم الخطر | — |\n| لا يُرجَّح أن يعرّض الأشخاص للخطر | غير مطلوب، ويُسجَّل السبب | غير مطلوب |\n| خطر على الأشخاص | مطلوب خلال 72 ساعة | غير مطلوب |\n| خطر مرتفع على الأشخاص | مطلوب خلال 72 ساعة | مطلوب دون تأخير غير مبرر، أو يُسجَّل سبب عدم الإبلاغ |\n\nعندما تحوي الأصول المتأثرة بيانات شخصية، يقترح الكتالوج مستوى: **مرتفع** للفئات الحساسة أو النطاق الواسع (100,000 صف فأكثر) أو أعمدة البيانات الشخصية غير المشفرة، وإلا **خطر**؛ و**غير مرجَّح** عندما لا تحوي أي بيانات شخصية. والقرار لمسؤول الامتثال.\n\nيبيّن السجل لكل خرق هل الإشعار مستحق، أو مستحق خلال 24 ساعة، أو متأخر، أو تم في الموعد أو متأخراً. ويذكّر فحص كل ساعة المسؤولَ عن المعالجة ومسؤولي الامتثال مرة عندما يتبقى أقل من 24 ساعة، ومرة عند انقضاء المهلة (الإعدادات › الجدولة › خروقات البيانات).'),
  ('helpdoc.data-breaches.how.title', E'How to use it', E'طريقة الاستخدام'),
  ('helpdoc.data-breaches.how.body', E'1. Anyone who suspects a breach clicks **Report a breach**, with a short description and when it became known. Compliance officers are notified at once.\n2. The compliance officer (or administrator) assigns a handler, adds the affected assets and records the risk.\n3. Notify the regulator and record when, with their reference; notify the data subjects when the risk is high. **Regulator report (PDF)** gives the details a notification asks for.\n4. Record the containment and prevention measures, then **Close** the breach. Bayanis lists anything still missing. A report that turns out not to involve personal data is closed as **Not a breach**.\n\nCompliance officers and administrators see every breach. The person who reported a breach, and its handler, see that breach; only officers, administrators and the handler can change it. Breaches are never deleted.', E'1. ينقر كل من يشتبه بخرق **الإبلاغ عن خرق**، مع وصف قصير ووقت العلم به. ويُشعَر مسؤولو الامتثال فوراً.\n2. يُسند مسؤول الامتثال (أو مدير النظام) مسؤولاً عن المعالجة، ويضيف الأصول المتأثرة، ويسجّل الخطر.\n3. أشعر الجهة المختصة وسجّل وقت الإشعار ورقم مرجعها، وأبلغ أصحاب البيانات عندما يكون الخطر مرتفعاً. ويوفر **تقرير الجهة المختصة (PDF)** التفاصيل التي يطلبها الإشعار.\n4. سجّل إجراءات الاحتواء والوقاية، ثم **أغلق** الخرق. ويعرض بيانيس ما ينقص إن وُجد. والبلاغ الذي يتبيّن أنه لا يمسّ بيانات شخصية يُغلق بوصفه **ليس خرقاً**.\n\nيرى مسؤولو الامتثال ومديرو النظام كل الخروقات. ويرى المُبلِّغ والمسؤول عن المعالجة الخرق الخاص بهما؛ ولا يغيّره إلا مسؤولو الامتثال ومديرو النظام والمسؤول عن المعالجة. ولا تُحذف الخروقات أبداً.'),
  ('helpdoc.getting-started.menu.body', E'| Part of the menu | What you find there |\n|---|---|\n| Top | Dashboard, your Homepage, Reports, AI Enrichment, Custom Assets and New Request |\n| Domains | Data Governance, Data Catalog (Data Assets, Glossaries, Data Lineage), Data Quality, Classification, Data Privacy (Data Retention, Data Subject Requests, Impact Assessments, Data Breaches), Data Sharing, Open Data and FOI Requests |\n| Administration | Users, tags, bulk operations, workflows, data sources, audit logs, configuration, AI providers, regulation setup, report KPIs and custom asset types (administrators only) |\n\nMenu items with sub-pages open and close with the arrow beside them. The menu only shows the domains you have access to.\n\nYour name at the top of the menu opens your profile, your requests, this Help Center and sign out. The globe icon changes the language.', E'| جزء القائمة | ما تجده فيه |\n|---|---|\n| الأعلى | لوحة التحكم، والصفحة الرئيسية، والتقارير، وإثراء الذكاء الاصطناعي، والأصول المخصصة، وطلب جديد |\n| النطاقات | حوكمة البيانات، وكتالوج البيانات (أصول البيانات، والمسارد، ومسار البيانات)، وجودة البيانات، والتصنيف، وخصوصية البيانات (الاحتفاظ بالبيانات، وطلبات أصحاب البيانات، وتقييمات الأثر، وخروقات البيانات)، ومشاركة البيانات، والبيانات المفتوحة، وطلبات حرية المعلومات |\n| الإدارة | المستخدمون، والوسوم، والعمليات المجمعة، وسير العمل، ومصادر البيانات، وسجلات التدقيق، والإعدادات، ومزودو الذكاء الاصطناعي، وإعداد الأنظمة واللوائح، ومؤشرات التقارير، وأنواع الأصول المخصصة (لمديري النظام فقط) |\n\nتُفتح عناصر القائمة التي لها صفحات فرعية وتُغلق بالسهم المجاور لها. ولا تعرض القائمة إلا النطاقات المتاحة لك.\n\nيفتح اسمك أعلى القائمة ملفك الشخصي وطلباتك ومركز المساعدة هذا وتسجيل الخروج. وتغيّر أيقونة الكرة الأرضية اللغة.'),
  ('helpdoc.roles-and-access.roles.body', E'| Role | Typical person | What they can do |\n|---|---|---|\n| Administrator | Data management office, platform owner | Everything, including Administration, configuration and final decisions |\n| Data Steward | Business or technical data steward | Edit metadata, manage quality rules, handle requests on the assets they look after |\n| Compliance Officer | Data protection officer, compliance team | Privacy work: data subject requests, impact assessment decisions, data breaches, retention, legal holds |\n| Viewer | Any employee | Search and read the catalog, raise requests |', E'| الدور | الشخص المعتاد | ما يستطيع فعله |\n|---|---|---|\n| مدير النظام | مكتب إدارة البيانات، مالك المنصة | كل شيء، بما في ذلك الإدارة والإعدادات والقرارات النهائية |\n| أمين البيانات | أمين بيانات من الأعمال أو من الجانب التقني | تعديل البيانات الوصفية، وإدارة قواعد الجودة، ومعالجة الطلبات على الأصول التي يتولاها |\n| مسؤول الامتثال | مسؤول حماية البيانات، فريق الامتثال | أعمال الخصوصية: طلبات أصحاب البيانات، وقرارات تقييمات الأثر، وخروقات البيانات، والاحتفاظ، والتجميد القانوني |\n| مشاهد | أي موظف | البحث في الكتالوج وقراءته، وتقديم الطلبات |');

-- Human work on the old English is kept (marked out of date below), never overwritten.
CREATE TEMP TABLE _keep209 ON COMMIT DROP AS
SELECT tr.key_id FROM bayanat.translations tr
JOIN bayanat.translation_keys tk ON tk.key_id = tr.key_id
JOIN _tr209 n ON n.key_code = tk.key_code
WHERE tr.language_code = 'ar' AND tr.status_code IN ('HUMAN_EDITED', 'VERIFIED') AND tk.base_text <> n.base_text;

UPDATE bayanat.translations tr SET status_code = 'STALE'
FROM bayanat.translation_keys tk, _tr209 n
WHERE tr.key_id = tk.key_id AND tk.key_code = n.key_code AND tk.base_text <> n.base_text AND tr.status_code <> 'MISSING';

UPDATE bayanat.translation_keys tk SET base_text = n.base_text
FROM _tr209 n WHERE tk.key_code = n.key_code AND tk.base_text <> n.base_text;

INSERT INTO bayanat.translation_keys (category_code, key_code, base_text)
SELECT 'HELP_DOCS', key_code, base_text FROM _tr209
ON CONFLICT (key_code) DO NOTHING;

INSERT INTO bayanat.translations (key_id, language_code, translated_text, status_code, model_ref_text, translated_at)
SELECT tk.key_id, 'ar', n.ar_text, 'AI_TRANSLATED', 'Anthropic Claude:claude-opus-5-5', now()
FROM _tr209 n
JOIN bayanat.translation_keys tk ON tk.key_code = n.key_code AND tk.base_text = n.base_text
WHERE tk.key_id NOT IN (SELECT key_id FROM _keep209)
ON CONFLICT (key_id, language_code) DO UPDATE
  SET translated_text = EXCLUDED.translated_text, status_code = 'AI_TRANSLATED',
      model_ref_text = EXCLUDED.model_ref_text, translated_at = now(), verified_at = NULL, verified_by_user_id = NULL
  WHERE bayanat.translations.status_code IN ('MISSING', 'STALE', 'AI_TRANSLATED')
     OR bayanat.translations.translated_text IS NULL;

COMMIT;
